        match self {
            Self::Legacy(pointer) => {
                if let Some(deleter) = unsafe { (*pointer).deleter } {
                    unsafe { deleter(pointer) };
                }
            }
            Self::Versioned(pointer) => {
                if let Some(deleter) = unsafe { (*pointer).deleter } {
                    unsafe { deleter(pointer) };
                }
